from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    groups = []  # Initialize a list to store the separated groups

    start = 0
    for i in range(len(paren_string)):
        if paren_string[i] == '(':
            start = i
        elif paren_string[i] == ')':
            groups.append(paren_string[start:i+1])  # Step 2: Identify and separate the groups of nested parentheses

    # Step 3: Ensure the groups are distinct and in the order they appear
    distinct_groups = []
    for group in groups:
        if group not in distinct_groups:
            distinct_groups.append(group)

    return distinct_groups

